import { createContext, useContext, useState, useCallback } from "react";

const Ctx = createContext();

export const MesajProvider = ({ children }) => {
  const [konusmalar, setKonusmalar] = useState([]);

  const konusmaAc = useCallback((partnerId, partnerAd, partnerRol) => {
    setKonsumas(prev => {
      const mevcut = prev.find(k => k.partnerId === partnerId);
      if (mevcut) return prev;
      return [...prev, {
        id: Date.now(),
        partnerId,
        partnerAd,
        partnerRol,
        mesajlar: [],
        sonOkuma: new Date().toISOString()
      }];
    });
  }, []);

  const mesajGonder = useCallback((konusmaId, metin, dosya = null) => {
    setKonsumas(prev => prev.map(k => {
      if (k.id !== konusmaId) return k;
      const yeniMesaj = {
        id: Date.now(),
        metin,
        dosya,
        gonderen: "ben",
        zaman: new Date().toISOString()
      };
      return {
        ...k,
        mesajlar: [...k.mesajlar, yeniMesaj],
        sonOkuma: new Date().toISOString()
      };
    }));
  }, []);

  const mesajGonderildi = useCallback((konusmaId, mesajId) => {
    setKonsumas(prev => prev.map(k => {
      if (k.id !== konusmaId) return k;
      return {
        ...k,
        mesajlar: k.mesajlar.map(m => m.id === mesajId ? { ...m, gonderen: "konusmaci" } : m)
      };
    }));
  }, []);

  const dosyaYukle = useCallback((dosya) => {
    return new Promise((resolve) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        resolve({
          tip: dosya.type.startsWith("image/") ? "img" : "pdf",
          ad: dosya.name,
          veri: e.target.result,
          boyut: dosya.size
        });
      };
      reader.readAsDataURL(dosya);
    });
  }, []);

  return (
    <Ctx.Provider value={{
      konusmalar,
      konusmaAc,
      mesajGonder,
      mesajGonderildi,
      dosyaYukle
    }}>
      {children}
    </Ctx.Provider>
  );
};

export const useMesaj = () => useContext(Ctx);
